//! G2 gate: KDBX read/write round trip against fixtures written by kdbxweb.
//!
//! The fixtures are generated by `.tmp-kdbxgen/gen.js` using **kdbxweb**, an
//! implementation independent of the Rust `keepass` crate this adapter wraps.
//! That independence matters: a file written and read by the same library proves
//! only self-consistency.
//!
//! Every fixture is additionally checked by `keepassxc-cli ls` in the generator
//! workflow, so each one is known-good to a third implementation too.
//!
//! Fixtures are committed under `tests/fixtures/`. Regenerate with:
//!
//! ```text
//! node .tmp-kdbxgen/gen.js
//! ```

use std::path::{Path, PathBuf};

use keepass_core::adapter::KeepassVault;
use keepass_core::api::{Credential, Vault, VaultTransaction};
use keepass_core::error::CoreError;
use secrecy::SecretString;

const PASSWORD: &str = "test-master-pw";

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
}

fn fixture(name: &str) -> PathBuf {
    fixtures().join(name)
}

fn credential() -> Credential {
    Credential {
        password: Some(SecretString::from(PASSWORD)),
        key_file: None,
    }
}

fn wrong_credential() -> Credential {
    Credential {
        password: Some(SecretString::from("definitely-not-the-password")),
        key_file: None,
    }
}

fn open(name: &str) -> KeepassVault {
    KeepassVault::open(&fixture(name), &credential())
        .unwrap_or_else(|e| panic!("opening {name} failed: {e}"))
}

// ---------------------------------------------------------------------------
// Version / cipher / KDF matrix
// ---------------------------------------------------------------------------

#[test]
fn opens_kdbx4_aes_argon2id() {
    let v = open("v4-aes-argon2id.kdbx");
    assert_eq!(v.entry_count(), 1);
    let id = v.entry_by_title("Example Login").expect("entry present");

    assert_eq!(
        v.unprotected_value(id, "UserName").unwrap().as_deref(),
        Some("alice")
    );
    assert_eq!(
        v.unprotected_value(id, "URL").unwrap().as_deref(),
        Some("https://example.com")
    );
    // CJK must survive the XML round trip.
    assert_eq!(
        v.unprotected_value(id, "Notes").unwrap().as_deref(),
        Some("多字节注释用于验证 CJK 往返")
    );
    // TOTP lives in the `otp` field as a full otpauth URI (Q12).
    let otp = v.unprotected_value(id, "otp").unwrap().unwrap_or_default();
    assert!(otp.starts_with("otpauth://totp/"), "got {otp}");
    assert!(v.is_protected(id, "Password").unwrap());
}

