#[test]
fn reads_attachments_byte_exact() {
    let v = open("v4-attachments.kdbx");
    let id = v.entry_by_title("With Files").expect("entry");

    let mut names = v.attachment_names(id).unwrap();
    names.sort();
    assert_eq!(
        names,
        vec!["binary.bin".to_string(), "note.txt".to_string()]
    );

    assert_eq!(
        v.attachment_bytes(id, "note.txt").unwrap(),
        b"attachment body\n"
    );
    // Bytes that break naive UTF-8 handling must survive untouched.
    assert_eq!(
        v.attachment_bytes(id, "binary.bin").unwrap(),
        vec![0u8, 1, 2, 253, 254, 255]
    );
}

#[test]
fn reads_history() {
    let v = open("v4-history.kdbx");
    let id = v.entry_by_title("History Entry").expect("entry");
    assert_eq!(v.history_count(id).unwrap(), 2);
}

#[test]
fn reads_custom_icon_and_icon_id() {
    let v = open("v4-custom-icons.kdbx");
    let id = v.entry_by_title("Icon Entry").expect("entry");

    let icon = v.custom_icon(id).unwrap().expect("custom icon bytes");
    assert!(
        icon.starts_with(&[0x89, b'P', b'N', b'G']),
        "expected PNG magic, got {:?}",
        &icon[..4.min(icon.len())]
    );

    // `keepass` normalises a custom icon to `Icon::Custom(id)` and discards the
    // literal IconID of 69, so `icon_id` must report "no built-in icon" while
    // `has_custom_icon` reports the truth.
    assert!(v.has_custom_icon(id).unwrap());
    assert_eq!(
        v.icon_id(id).unwrap(),
        None,
        "a custom icon is not a built-in id"
    );
}

// ---------------------------------------------------------------------------
// Interop with the HarmonyOS client
// ---------------------------------------------------------------------------

#[test]
fn reads_harmonyos_private_markers() {
    let v = open("v4-homo-markers.kdbx");
    let login = v.entry_by_title("Homo Login").expect("login entry");

    // The fixture deliberately avoids literal "true"/"false": `keepass` 0.17
    // mis-parses those as base64. See `favorite_true_is_unreadable_upstream`.
    assert_eq!(
        v.custom_data(login, keepass_core::interop::KEY_FAVORITE)
            .unwrap()
            .as_deref(),
        Some("yes")
    );
    assert_eq!(
        v.custom_data(login, keepass_core::interop::KEY_ARCHIVED)
            .unwrap()
            .as_deref(),
        Some("no")
    );
    assert_eq!(
        v.custom_data(login, keepass_core::interop::KEY_LAYOUT_TYPE)
            .unwrap()
            .as_deref(),
        Some("Login")
    );

    let types = v
        .custom_data(login, keepass_core::interop::KEY_FIELD_TYPES)
        .unwrap()
        .expect("field types json");
    let parsed: serde_json::Value = serde_json::from_str(&types).unwrap();
    assert_eq!(parsed["URL"], "url");
    assert_eq!(parsed["Notes"], "custom");

    // SshKeys is a real protected FIELD holding versioned JSON.
    let ssh = v.entry_by_title("Homo SSH").expect("ssh entry");
    assert!(
        v.is_protected(ssh, keepass_core::interop::FIELD_SSH_KEYS)
            .unwrap()
    );
    assert!(v.field_names(ssh).unwrap().contains(&"SshKeys".to_string()));
}

/// Pins an upstream defect we must live with.
///
/// `keepass` 0.17 deserialises `customData` values by trying base64 first.
/// The literal `"true"` — which is exactly what `KeePassHomo.Favorite` stores —
/// is valid base64, so the parser yields `Binary` and the text is destroyed
/// irreversibly (3 bytes that are not UTF-8).
///
/// This test asserts the *broken* behaviour on purpose. When upstream fixes it,
/// this test fails, and that failure is the signal to delete the workaround note
/// in `KeepassVault::custom_data` and architecture.md §13.
#[test]
fn favorite_true_is_unreadable_upstream() {
    let v = open("v4-homo-favorite-true.kdbx");
    let id = v.entry_by_title("True Favorite").expect("entry");

    let got = v
        .custom_data(id, keepass_core::interop::KEY_FAVORITE)
        .unwrap();

    // The marker is present in the file (kdbxweb and KeePassXC both see it) but
    // not recoverable through this crate. `None` here documents the defect.
    assert_eq!(
        got, None,
        "upstream fixed the base64 mis-parse? Remove the workaround and this test"
    );
}

#[test]
fn entry_count_covers_all_groups() {
    let v = open("v4-homo-markers.kdbx");
    assert_eq!(v.entry_count(), 2);
}

// ---------------------------------------------------------------------------
// Error classification
// ---------------------------------------------------------------------------

#[test]
fn wrong_password_is_bad_credential() {
    // This test locks the message-based matching in `classify_open_error`. If a
    // future keepass release rewords `IncorrectKey`, this fails loudly instead
    // of reporting corruption to the user.
    let err = KeepassVault::open(&fixture("v4-aes-argon2id.kdbx"), &wrong_credential())
        .expect_err("wrong password must not open");
    assert!(
        matches!(err, CoreError::BadCredential),
        "expected BadCredential, got {err:?}"
    );
}

#[test]
fn non_kdbx_file_is_rejected_as_not_a_vault() {
    let tmp = std::env::temp_dir().join("keepass-core-not-a-vault.kdbx");
    std::fs::write(&tmp, b"this is definitely not a kdbx file").unwrap();

    let err = KeepassVault::open(&tmp, &credential()).expect_err("must reject");
    assert!(
        matches!(err, CoreError::NotAKdbxFile),
        "expected NotAKdbxFile, got {err:?}"
    );
    let _ = std::fs::remove_file(&tmp);
}

#[test]
fn truncated_file_is_corrupt_not_bad_credential() {
    let full = std::fs::read(fixture("v4-aes-argon2id.kdbx")).unwrap();
    let tmp = std::env::temp_dir().join("keepass-core-truncated.kdbx");
    // Keep the signature (first 12 bytes) but cut the body.
    std::fs::write(&tmp, &full[..full.len() / 2]).unwrap();

    let err = KeepassVault::open(&tmp, &credential()).expect_err("must reject");
    assert!(
        matches!(err, CoreError::Corrupt { .. }),
        "expected Corrupt, got {err:?}"
    );
    let _ = std::fs::remove_file(&tmp);
}

#[test]
fn missing_key_file_is_reported_as_io() {
    let cred = Credential {
        password: None,
        key_file: Some(PathBuf::from("E:\\does\\not\\exist.keyx")),
    };
    let err = KeepassVault::open(&fixture("v4-aes-argon2id-keyfile.kdbx"), &cred)
        .expect_err("must reject");
    assert!(matches!(err, CoreError::Io { .. }), "got {err:?}");
}

