// ---------------------------------------------------------------------------
// Round trip: read -> write -> read -> compare
// ---------------------------------------------------------------------------

fn round_trip(name: &str, entry_title: &str) {
    let src = fixture(name);
    let work = std::env::temp_dir().join(format!("keepass-core-rt-{name}"));
    std::fs::copy(&src, &work).expect("copy fixture");

    // Read, mutate, save.
    {
        let mut v = KeepassVault::open(&work, &credential()).expect("open copy");
        let id = v.entry_by_title(entry_title).expect("entry");
        v.apply(VaultTransaction::SetTitle {
            entry: id,
            value: "Renamed By Round Trip".into(),
        })
        .expect("apply title");
        v.save(&credential()).expect("save");
    }

    // Re-open and verify both the change and the untouched data.
    {
        let v = KeepassVault::open(&work, &credential()).expect("reopen");
        let id = v
            .entry_by_title("Renamed By Round Trip")
            .expect("renamed entry survived");
        assert!(
            v.is_protected(id, "Password").unwrap(),
            "protection must persist"
        );
    }

    let _ = std::fs::remove_file(&work);
}

#[test]
fn round_trip_kdbx4_aes() {
    round_trip("v4-aes-argon2id.kdbx", "Example Login");
}

#[test]
fn round_trip_kdbx4_chacha20() {
    round_trip("v4-chacha20-argon2id.kdbx", "ChaCha Entry");
}

#[test]
fn round_trip_preserves_attachments() {
    let work = std::env::temp_dir().join("keepass-core-rt-att.kdbx");
    std::fs::copy(fixture("v4-attachments.kdbx"), &work).unwrap();

    {
        let mut v = KeepassVault::open(&work, &credential()).unwrap();
        let id = v.entry_by_title("With Files").unwrap();
        v.apply(VaultTransaction::SetFavorite {
            entry: id,
            value: true,
        })
        .unwrap();
        v.save(&credential()).unwrap();
    }
    {
        let v = KeepassVault::open(&work, &credential()).unwrap();
        let id = v.entry_by_title("With Files").unwrap();
        assert_eq!(
            v.attachment_bytes(id, "binary.bin").unwrap(),
            vec![0u8, 1, 2, 253, 254, 255],
            "attachment bytes must survive a save"
        );
    }
    let _ = std::fs::remove_file(&work);
}

#[test]
fn round_trip_preserves_foreign_custom_data() {
    // The HarmonyOS client deletes any field it does not model. We must not: an
    // unknown marker written by a third client has to survive our save.
    let work = std::env::temp_dir().join("keepass-core-rt-foreign.kdbx");
    std::fs::copy(fixture("v4-homo-markers.kdbx"), &work).unwrap();

    {
        let mut v = KeepassVault::open(&work, &credential()).unwrap();
        let id = v.entry_by_title("Homo Login").unwrap();
        // Touch an unrelated marker.
        v.apply(VaultTransaction::SetArchived {
            entry: id,
            value: true,
        })
        .unwrap();
        v.save(&credential()).unwrap();
    }
    {
        let v = KeepassVault::open(&work, &credential()).unwrap();
        let id = v.entry_by_title("Homo Login").unwrap();
        // Favorite was untouched and must still be there.
        assert_eq!(
            v.custom_data(id, keepass_core::interop::KEY_FAVORITE)
                .unwrap()
                .as_deref(),
            Some("yes")
        );
        // The field-type JSON must survive too.
        assert!(
            v.custom_data(id, keepass_core::interop::KEY_FIELD_TYPES)
                .unwrap()
                .is_some()
        );
    }
    let _ = std::fs::remove_file(&work);
}

#[test]
fn write_markers_are_readable_by_ourselves() {
    let work = std::env::temp_dir().join("keepass-core-write-markers.kdbx");
    std::fs::copy(fixture("v4-aes-argon2id.kdbx"), &work).unwrap();

    {
        let mut v = KeepassVault::open(&work, &credential()).unwrap();
        let id = v.entry_by_title("Example Login").unwrap();
        v.apply(VaultTransaction::SetFavorite {
            entry: id,
            value: true,
        })
        .unwrap();
        v.apply(VaultTransaction::SetArchived {
            entry: id,
            value: false,
        })
        .unwrap();
        v.save(&credential()).unwrap();
    }
    {
        let v = KeepassVault::open(&work, &credential()).unwrap();
        assert_eq!(v.count_with_marker(keepass_core::interop::KEY_FAVORITE), 1);
        assert_eq!(v.count_with_marker(keepass_core::interop::KEY_ARCHIVED), 1);
        // Validation is dead code upstream; we must never write it.
        assert_eq!(
            v.count_with_marker(keepass_core::interop::KEY_VALIDATION),
            0
        );
    }
    let _ = std::fs::remove_file(&work);
}

// ---------------------------------------------------------------------------
// Q29: stale-write refusal
// ---------------------------------------------------------------------------

#[test]
fn save_refuses_when_file_changed_underneath() {
    let work = std::env::temp_dir().join("keepass-core-stale.kdbx");
    std::fs::copy(fixture("v4-aes-argon2id.kdbx"), &work).unwrap();

    let mut v = KeepassVault::open(&work, &credential()).unwrap();
    let id = v.entry_by_title("Example Login").unwrap();
    v.apply(VaultTransaction::SetTitle {
        entry: id,
        value: "local edit".into(),
    })
    .unwrap();

    // Simulate another client (the HarmonyOS app) rewriting the file.
    std::thread::sleep(std::time::Duration::from_millis(20));
    std::fs::write(&work, b"another client wrote here").unwrap();

    let err = v.save(&credential()).expect_err("must refuse");
    assert!(
        matches!(err, CoreError::FileChangedExternally),
        "expected FileChangedExternally, got {err:?}"
    );

    // The foreign bytes must be exactly what the other client wrote.
    assert_eq!(
        std::fs::read(&work).unwrap(),
        b"another client wrote here",
        "a refused save must not touch the file"
    );

    let _ = std::fs::remove_file(&work);
}

#[test]
fn save_leaves_no_temp_or_backup_files() {
    let work = std::env::temp_dir().join("keepass-core-tidy.kdbx");
    std::fs::copy(fixture("v4-aes-argon2id.kdbx"), &work).unwrap();

    let mut v = KeepassVault::open(&work, &credential()).unwrap();
    let id = v.entry_by_title("Example Login").unwrap();
    v.apply(VaultTransaction::SetFavorite {
        entry: id,
        value: true,
    })
    .unwrap();
    v.save(&credential()).unwrap();

    let base = work.to_string_lossy().to_string();
    assert!(
        !Path::new(&format!("{base}.tmp")).exists(),
        "temp file left behind"
    );
    assert!(
        !Path::new(&format!("{base}.bak")).exists(),
        "backup file left behind"
    );

    let _ = std::fs::remove_file(&work);
}

