#[test]
fn verify_credential_accepts_right_and_rejects_wrong() {
    let v = open("v4-aes-argon2id.kdbx");
    assert!(v.verify_credential(&credential()).unwrap());
    assert!(!v.verify_credential(&wrong_credential()).unwrap());
}

// ---------------------------------------------------------------------------
// Fixture hygiene
// ---------------------------------------------------------------------------

#[test]
fn all_fixtures_open() {
    for name in [
        "v3.1-aes-aeskdf.kdbx",
        "v4-aes-argon2id.kdbx",
        "v4.1-aes-argon2id.kdbx",
        "v4-chacha20-argon2id.kdbx",
        "v4-attachments.kdbx",
        "v4-history.kdbx",
        "v4-custom-icons.kdbx",
        "v4-homo-markers.kdbx",
    ] {
        let v = open(name);
        assert!(v.entry_count() >= 1, "{name} has no entries");
        assert!(v.still_current().unwrap(), "{name} identity mismatch");
    }
}
